const flappyHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no" />
  <title>Flappy Bird</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap');
    
    body, html {
      margin: 0;
      padding: 0;
      width: 100vw;
      height: 100vh;
      overflow: hidden;
      background-color: #71c5cf;
      touch-action: none; /* prevent pull-to-refresh */
      font-family: 'Press Start 2P', cursive;
    }

    #gameCanvas {
      display: block;
      width: 100vw;
      height: 100vh;
    }

    /* Simple UI overlay */
    #ui {
      position: absolute;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100vh;
      pointer-events: none;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    #score {
      position: absolute;
      top: 15%;
      font-size: 40px;
      color: white;
      text-shadow: 2px 2px 0 #000, -2px -2px 0 #000, 2px -2px 0 #000, -2px 2px 0 #000;
      z-index: 10;
    }

    #menu {
      background: rgba(0, 0, 0, 0.5);
      padding: 20px 40px;
      border-radius: 10px;
      text-align: center;
      pointer-events: auto; /* Allow clicking start */
    }

    #menu h1 {
      color: #fff;
      font-size: 24px;
      margin-top: 0;
      text-shadow: 2px 2px 0 #000;
    }

    #menu button {
      background: #f6a830;
      border: 4px solid #fff;
      color: #fff;
      font-family: 'Press Start 2P', cursive;
      font-size: 16px;
      padding: 15px 20px;
      cursor: pointer;
      text-shadow: 1px 1px 0 #000;
      box-shadow: 0 4px 0 #000;
      border-radius: 8px;
    }

    #menu button:active {
      transform: translateY(4px);
      box-shadow: 0 0px 0 #000;
    }
    
    #characterSelect {
      margin-bottom: 20px;
    }
    .birds-container {
      display: flex;
      justify-content: center;
      gap: 10px;
      flex-wrap: wrap;
    }
    .bird-option {
      width: 34px;
      height: 24px;
      background-image: url('https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/yellowbird-midflap.png');
      background-size: cover;
      cursor: pointer;
      border: 2px solid transparent;
      border-radius: 4px;
      margin-bottom: 5px;
    }
    .bird-option.selected {
      border-color: white;
    }
    .bird-option[data-index="1"] { filter: hue-rotate(180deg); }
    .bird-option[data-index="2"] { filter: hue-rotate(300deg); }
    .bird-option[data-index="3"] { filter: hue-rotate(60deg); }
    .bird-option[data-index="4"] { filter: hue-rotate(240deg); }
    .bird-option[data-index="5"] { filter: hue-rotate(120deg); }

    .hidden {
      display: none !important;
    }
  </style>
</head>
<body>
  <canvas id="gameCanvas"></canvas>
  <div id="ui">
    <div id="score">0</div>
    <div id="menu">
      <h1>FLAPPY BIRD</h1>
      <p style="color: white; font-size: 10px; line-height: 1.5; margin-bottom: 20px;">Tap to jump.<br>Avoid the pipes.</p>
      <div id="characterSelect">
        <p style="color: white; font-size: 12px; margin-bottom: 10px;">Select Bird:</p>
        <div class="birds-container">
          <div class="bird-option selected" data-index="0"></div>
          <div class="bird-option" data-index="1"></div>
          <div class="bird-option" data-index="2"></div>
          <div class="bird-option" data-index="3"></div>
          <div class="bird-option" data-index="4"></div>
          <div class="bird-option" data-index="5"></div>
        </div>
      </div>
      <button id="startBtn">START</button>
    </div>
  </div>

  <script>
    // Force 1x pixel ratio for massive performance boost on low-end androids
    Object.defineProperty(window, 'devicePixelRatio', { get: () => 1 });
    
    window.onerror = function(msg, url, line, col, err) {
      window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'error', message: msg + ' at ' + line + ':' + col }));
    };
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d', { alpha: false });
    ctx.imageSmoothingEnabled = false; // Disable bilinear filtering for better performance
    const scoreElement = document.getElementById('score');
    const menuElement = document.getElementById('menu');
    const startBtn = document.getElementById('startBtn');

    // Make canvas full screen
    function resizeCanvas() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    let selectedBirdIndex = 0;
    const birdOptions = document.querySelectorAll('.bird-option');
    birdOptions.forEach(option => {
      option.addEventListener('click', (e) => {
        e.stopPropagation();
        birdOptions.forEach(opt => opt.classList.remove('selected'));
        option.classList.add('selected');
        selectedBirdIndex = parseInt(option.getAttribute('data-index'));
      });
      option.addEventListener('touchstart', (e) => {
        e.stopPropagation();
        birdOptions.forEach(opt => opt.classList.remove('selected'));
        option.classList.add('selected');
        selectedBirdIndex = parseInt(option.getAttribute('data-index'));
      }, { passive: false });
    });

    // Game state
    let frames = 0;
    let currentScore = 0;
    let gameState = 'START'; // START, PLAYING, GAMEOVER
    let animationId;

    const birdSets = {};
    function generateBirds() {
      const urls = {
        mid: 'https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/yellowbird-midflap.png',
        up: 'https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/yellowbird-upflap.png',
        down: 'https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/yellowbird-downflap.png'
      };
      const modes = [
        (r,g,b) => [r, g, b], // 0: Yellow
        (r,g,b) => [b, g, r], // 1: Blue-ish
        (r,g,b) => [r, b, g], // 2: Pink-ish
        (r,g,b) => [g, r, b], // 3: Green-ish
        (r,g,b) => [b, r, g], // 4: Purple-ish
        (r,g,b) => [g, b, r]  // 5: Cyan-ish
      ];
      modes.forEach((modeFn, index) => {
        birdSets[index] = {};
        Object.keys(urls).forEach(key => {
          const img = new Image();
          img.crossOrigin = 'Anonymous';
          img.onload = () => {
            const c = document.createElement('canvas');
            c.width = img.width; c.height = img.height;
            const cx = c.getContext('2d', {willReadFrequently: true});
            cx.drawImage(img, 0, 0);
            if (index !== 0) {
              const imgData = cx.getImageData(0, 0, c.width, c.height);
              const data = imgData.data;
              for (let i = 0; i < data.length; i += 4) {
                if (data[i+3] === 0) continue;
                const r = data[i], g = data[i+1], b = data[i+2];
                const [nr, ng, nb] = modeFn(r, g, b);
                data[i] = nr; data[i+1] = ng; data[i+2] = nb;
              }
              cx.putImageData(imgData, 0, 0);
            }
            const resImg = new Image();
            resImg.src = c.toDataURL();
            birdSets[index][key] = resImg;
          };
          img.src = urls[key];
        });
      });
    }
    generateBirds();

    const bgImg = new Image();
    bgImg.src = 'https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/background-day.png';

    const pipeImg = new Image();
    pipeImg.src = 'https://raw.githubusercontent.com/samuelcust/flappy-bird-assets/master/sprites/pipe-green.png';

    const seasonalBgs = {};
    const seasonalPipes = {};

    function generateSeasonalAssets() {
      const bImg = new Image();
      bImg.crossOrigin = 'Anonymous';
      bImg.onload = () => {
        seasons.forEach(season => {
          const c = document.createElement('canvas');
          c.width = bImg.width; c.height = bImg.height;
          const cx = c.getContext('2d', {willReadFrequently: true});
          if (season.name === 'Autumn') cx.filter = 'sepia(0.5) hue-rotate(-30deg)';
          else if (season.name === 'Winter') cx.filter = 'grayscale(0.5) brightness(0.8)';
          else if (season.name === 'Spring') cx.filter = 'hue-rotate(45deg)';
          cx.drawImage(bImg, 0, 0);
          const resImg = new Image();
          resImg.src = c.toDataURL();
          seasonalBgs[season.name] = resImg;
        });
      };
      bImg.src = bgImg.src;

      const pImg = new Image();
      pImg.crossOrigin = 'Anonymous';
      pImg.onload = () => {
        seasons.forEach(season => {
          const c = document.createElement('canvas');
          c.width = pImg.width; c.height = pImg.height;
          const cx = c.getContext('2d', {willReadFrequently: true});
          if (season.name === 'Autumn') cx.filter = 'sepia(0.5) hue-rotate(-30deg)';
          else if (season.name === 'Winter') cx.filter = 'grayscale(0.5) brightness(1.2)';
          else if (season.name === 'Spring') cx.filter = 'hue-rotate(90deg)';
          cx.drawImage(pImg, 0, 0);
          const resImg = new Image();
          resImg.src = c.toDataURL();
          seasonalPipes[season.name] = resImg;
        });
      };
      pImg.src = pipeImg.src;
    }
    generateSeasonalAssets();

    const seasons = [
      { name: 'Spring', bg: '#71c5cf', groundBase: '#ded895', groundTop: '#73bf2e', pipe: '#73bf2e' },
      { name: 'Summer', bg: '#4cb5f5', groundBase: '#c19a6b', groundTop: '#2d882d', pipe: '#2d882d' },
      { name: 'Autumn', bg: '#ff9a00', groundBase: '#8b5a2b', groundTop: '#d2691e', pipe: '#a0522d' },
      { name: 'Winter', bg: '#a3c2c2', groundBase: '#ffffff', groundTop: '#e0e0e0', pipe: '#b0e0e6' }
    ];

    function getCurrentSeason() {
      return seasons[Math.floor(currentScore / 10) % seasons.length];
    }

    
    const audioSwoosh = new Audio('data:audio/mp3;base64,' + '');
    const audioPoint = new Audio('data:audio/mp3;base64,' + '');
    const audioHit = new Audio('data:audio/mp3;base64,' + '');
    
    function playSwoosh() { audioSwoosh.currentTime = 0; audioSwoosh.play().catch(e=>console.log(e)); }
    function playPoint() { audioPoint.currentTime = 0; audioPoint.play().catch(e=>console.log(e)); }
    function playHit() { audioHit.currentTime = 0; audioHit.play().catch(e=>console.log(e)); }

    // Game Objects
    const bird = {
      x: canvas.width / 3,
      y: canvas.height / 2,
      radius: 14,
      velocity: 0,
      gravity: 0.4, // Adjusted for responsiveness
      jump: -7,
      draw: function() {
        let set = birdSets[selectedBirdIndex];
        if (!set || !set.mid) set = birdSets[0]; // default
        
        if (set && set.mid && set.mid.complete) {
          let img = set.mid;
          if (this.velocity < -2) img = set.up;
          else if (this.velocity > 2) img = set.down;
          
          ctx.save();
          ctx.translate(Math.round(this.x), Math.round(this.y));
          let rotation = Math.min(Math.PI / 4, Math.max(-Math.PI / 4, (this.velocity * 0.1)));
          ctx.rotate(rotation);
          ctx.drawImage(img, -17, -12, 34, 24);
          ctx.restore();
        } else {
          ctx.save();
          ctx.beginPath();
          ctx.arc(Math.round(this.x), Math.round(this.y), this.radius, 0, Math.PI * 2);
          const colors = ['#f6d743', '#43d7f6', '#f643d7', '#d7f643', '#d743f6', '#43f6d7'];
          ctx.fillStyle = colors[selectedBirdIndex] || '#f6d743';
          ctx.fill();
          ctx.lineWidth = 2;
          ctx.strokeStyle = '#000';
          ctx.stroke();
          ctx.restore();
        }
      },
      update: function(timeScale = 1) {
        if (gameState === 'PLAYING') {
          this.velocity += this.gravity * timeScale;
          this.y += this.velocity * timeScale;

          // Ground collision
          if (this.y + this.radius >= canvas.height - 50) {
            this.y = canvas.height - 50 - this.radius;
            gameOver();
          }

          // Ceiling collision
          if (this.y - this.radius <= 0) {
            this.y = this.radius;
            this.velocity = 0;
          }
        }
      },
      flap: function() {
        this.velocity = this.jump;
        // playSwoosh(); // Commented out to prevent game hanging/lagging on tap
      },
      reset: function() {
        this.y = canvas.height / 2;
        this.velocity = 0;
      }
    };

    let pipeTimer = 0;

    const pipes = {
      items: [],
      width: 60,
      gap: 160,
      dx: 3, // speed
      draw: function() {
        const season = getCurrentSeason();
        for (let i = 0; i < this.items.length; i++) {
          let p = this.items[i];
          
          let img = seasonalPipes[season.name];
          if (!img || !img.complete) img = pipeImg; // fallback

          if (img.complete && img.naturalHeight !== 0) {
             // Top pipe (flipped)
             ctx.save();
             ctx.translate(Math.round(p.x), Math.round(p.top));
             ctx.scale(1, -1);
             ctx.drawImage(img, 0, 0, this.width, Math.round(p.top));
             ctx.restore();

             // Bottom pipe
             let bottomY = Math.round(p.top + this.gap);
             ctx.drawImage(img, Math.round(p.x), bottomY, this.width, Math.round(canvas.height - bottomY - 50));
          } else {
             ctx.fillStyle = season.pipe;
             ctx.lineWidth = 2;
             ctx.strokeStyle = '#000';

             let topY = Math.round(p.top);
             let px = Math.round(p.x);

             // Top pipe
             ctx.fillRect(px, 0, this.width, topY);
             ctx.strokeRect(px, 0, this.width, topY);
             // Top pipe cap
             ctx.fillRect(px - 4, topY - 20, this.width + 8, 20);
             ctx.strokeRect(px - 4, topY - 20, this.width + 8, 20);
             
             // Bottom pipe
             let bottomY = Math.round(p.top + this.gap);
             let bottomH = Math.round(canvas.height - bottomY - 50);
             ctx.fillRect(px, bottomY, this.width, bottomH);
             ctx.strokeRect(px, bottomY, this.width, bottomH);
             // Bottom pipe cap
             ctx.fillRect(px - 4, bottomY, this.width + 8, 20);
             ctx.strokeRect(px - 4, bottomY, this.width + 8, 20);
          }
        }
      },
      update: function(timeScale = 1) {
        if (gameState !== 'PLAYING') return;

        pipeTimer += timeScale;
        if (pipeTimer >= 100) {
          pipeTimer -= 100;
          // min pipe height is 50, gap is 160, ground is 50
          let maxYPos = canvas.height - 50 - this.gap - 50; 
          let topPipeHeight = Math.max(50, Math.random() * maxYPos);
          
          this.items.push({
            x: canvas.width,
            top: topPipeHeight,
            passed: false
          });
        }

        for (let i = 0; i < this.items.length; i++) {
          let p = this.items[i];
          p.x -= this.dx * timeScale;

          // Collision detection
          // X collision
          if (bird.x + bird.radius > p.x && bird.x - bird.radius < p.x + this.width) {
            // Y collision
            if (bird.y - bird.radius < p.top || bird.y + bird.radius > p.top + this.gap) {
              gameOver();
            }
          }

          // Score update
          if (p.x + this.width < bird.x && !p.passed) {
            currentScore++;
            playPoint();
            scoreElement.innerText = currentScore;
            p.passed = true;
          }

          // Remove pipes that are off screen
          if (p.x + this.width < 0) {
            this.items.shift();
            i--;
          }
        }
      },
      reset: function() {
        this.items = [];
      }
    };

    const ground = {
      y: canvas.height - 50,
      h: 50,
      x: 0,
      dx: 3,
      draw: function() {
        // We have to redraw ground properly when canvas resizes
        this.y = Math.round(canvas.height - 50);
        const season = getCurrentSeason();
        
        ctx.fillStyle = season.groundBase;
        ctx.fillRect(0, this.y, canvas.width, this.h);
        
        ctx.fillStyle = season.groundTop;
        ctx.fillRect(0, this.y, canvas.width, 10);
        
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, this.y);
        ctx.lineTo(canvas.width, this.y);
        ctx.stroke();
      }
    };

    function draw() {
      const season = getCurrentSeason();
      // Clear canvas
      ctx.fillStyle = season.bg;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      let img = seasonalBgs[season.name];
      if (!img || !img.complete) img = bgImg; // fallback

      if (img.complete && img.naturalHeight !== 0) {
        let bgWidth = canvas.height * (288 / 512);
        for(let i = 0; i < canvas.width; i += bgWidth) {
          ctx.drawImage(img, Math.round(i), 0, Math.round(bgWidth), canvas.height);
        }
      }

      pipes.draw();
      ground.draw();
      bird.draw();
    }

    let lastTime = 0;

    function update(timeScale = 1) {
      bird.update(timeScale);
      pipes.update(timeScale);
      frames += timeScale;
    }

    function loop(timestamp) {
      if (!lastTime) lastTime = timestamp;
      let deltaTime = timestamp - lastTime;
      if (deltaTime > 50) deltaTime = 16.666;
      lastTime = timestamp;

      update(deltaTime / 16.666);
      draw();
      animationId = requestAnimationFrame(loop);
    }

    function startGame() {
      gameState = 'PLAYING';
      bird.reset();
      pipes.reset();
      currentScore = 0;
      frames = 0;
      pipeTimer = 0;
      scoreElement.innerText = currentScore;
      menuElement.classList.add('hidden');
      scoreElement.classList.remove('hidden');
      lastTime = 0;
    }

    function gameOver() {
      gameState = 'GAMEOVER';
      playHit();
      menuElement.classList.remove('hidden');
      menuElement.querySelector('h1').innerText = 'GAME OVER';
    }

    // Input handling
    function handleInput(e) {
      // prevent default to avoid scrolling
      if (e.cancelable && gameState === 'PLAYING') {
         e.preventDefault(); 
      }
      
      if (gameState === 'PLAYING') {
        bird.flap();
      } else if (gameState === 'GAMEOVER') {
        // Wait a tiny bit before allowing restart so user doesn't accidentally double tap
        setTimeout(() => {
          startGame();
        }, 300);
      }
    }

    startBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      startGame();
    });

    window.addEventListener('touchstart', (e) => {
      if (e.target.closest('#menu')) return;
      handleInput(e);
    }, { passive: false });
    window.addEventListener('mousedown', (e) => {
      if (e.target.closest('#menu')) return;
      handleInput(e);
    });

    // Start drawing the initial state
    scoreElement.classList.add('hidden');
    draw();
    animationId = requestAnimationFrame(loop);
  </script>
</body>
</html>`;

export default flappyHtml;
